pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testRegression_property() public {
        c.SetMinSum(1);
        address dummyLog = address(new LogFile());
        c.SetLogFile(dummyLog);
        c.Initialized();
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 1 ether}();
        bool ok;
        vm.prank(alice);
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
